(window.webpackJsonp=window.webpackJsonp||[]).push([[41],{491:function(n,e,r){"use strict";r.r(e);var a=r(25),t=Object(a.a)({},(function(){var n=this._self._c;return n("ContentSlotsDistributor",{attrs:{"slot-key":this.$parent.slotKey}},[n("h1",{attrs:{id:"_4-coloredpoints-不同颜色的点"}},[n("a",{staticClass:"header-anchor",attrs:{href:"#_4-coloredpoints-不同颜色的点"}},[this._v("#")]),this._v(" 4/coloredPoints 不同颜色的点")]),this._v(" "),n("div",{staticClass:"language- extra-class"},[n("pre",{pre:!0,attrs:{class:"language-text"}},[n("code",[this._v("/**\n * Create a program object and make current\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return true, if the program object was created and successfully made current \n */\nfunction initShaders(gl, vshader, fshader) {\n  var program = createProgram(gl, vshader, fshader);\n  if (!program) {\n    console.log('Failed to create program');\n    return false;\n  }\n\n  gl.useProgram(program);\n  gl.program = program;\n\n  return true;\n}\n\n/**\n * Create the linked program object\n * @param gl GL context\n * @param vshader a vertex shader program (string)\n * @param fshader a fragment shader program (string)\n * @return created program object, or null if the creation has failed\n */\nfunction createProgram(gl, vshader, fshader) {\n  // Create shader object\n  var vertexShader = loadShader(gl, gl.VERTEX_SHADER, vshader);\n  var fragmentShader = loadShader(gl, gl.FRAGMENT_SHADER, fshader);\n  if (!vertexShader || !fragmentShader) {\n    return null;\n  }\n\n  // Create a program object\n  var program = gl.createProgram();\n  if (!program) {\n    return null;\n  }\n\n  // Attach the shader objects\n  gl.attachShader(program, vertexShader);\n  gl.attachShader(program, fragmentShader);\n\n  // Link the program object\n  gl.linkProgram(program);\n\n  // Check the result of linking\n  var linked = gl.getProgramParameter(program, gl.LINK_STATUS);\n  if (!linked) {\n    var error = gl.getProgramInfoLog(program);\n    console.log('Failed to link program: ' + error);\n    gl.deleteProgram(program);\n    gl.deleteShader(fragmentShader);\n    gl.deleteShader(vertexShader);\n    return null;\n  }\n  return program;\n}\n\n/**\n * Create a shader object\n * @param gl GL context\n * @param type the type of the shader object to be created\n * @param source shader program (string)\n * @return created shader object, or null if the creation has failed.\n */\nfunction loadShader(gl, type, source) {\n  // Create shader object\n  var shader = gl.createShader(type);\n  if (shader == null) {\n    console.log('unable to create shader');\n    return null;\n  }\n\n  // Set the shader program\n  gl.shaderSource(shader, source);\n\n  // Compile the shader\n  gl.compileShader(shader);\n\n  // Check the result of compilation\n  var compiled = gl.getShaderParameter(shader, gl.COMPILE_STATUS);\n  if (!compiled) {\n    var error = gl.getShaderInfoLog(shader);\n    console.log('Failed to compile shader: ' + error);\n    gl.deleteShader(shader);\n    return null;\n  }\n\n  return shader;\n}\n\n\nfunction initWebGL(canvas) {\n  const dpr = window.devicePixelRatio || 1;\n  console.log(dpr);\n  canvas.width = 400 * dpr;\n  canvas.height = 300 * dpr;\n  canvas.style.width = '400px';\n  canvas.style.height = '300px'\n\n  const gl = canvas.getContext('webgl');\n  if (!gl) {\n    console.error('Failed to get WebGL context');\n    return null;\n  }\n  gl.viewport(0, 0, canvas.width, canvas.height);\n  gl.clearColor(0, 0, 0, 1);\n  return gl;\n}\n\n\nfunction getWebGLCoord(canvas, clientX, clientY) {\n  const dpr = window.devicePixelRatio || 1;\n  const rect = canvas.getBoundingClientRect();\n\n  // CSS → 物理像素\n  const x = (clientX - rect.left) * dpr;\n  const y = (clientY - rect.top) * dpr;\n\n  // 物理像素 → WebGL NDC\n  return [\n    (x / canvas.width) * 2 - 1,\n    -((y / canvas.height) * 2 - 1)\n  ];\n}\n\nwindow.onload = function(){\n    // 将十六进制转为rgba值\n    function hexToRgba(hex){\n        // 首先使用正则表达式将十六进制字符串分解为 RGB 分量\n        let result;\n        if (hex.length === 4) {\n            result = /^#?([a-f\\d])([a-f\\d])([a-f\\d])$/i.exec(hex);\n            // 将分解出的分量转换为十进制数，并将它们扩展为 6 位十六进制字符串\n            let r = parseInt(result[1] + result[1], 16);\n            let g = parseInt(result[2] + result[2], 16);\n            let b = parseInt(result[3] + result[3], 16);\n            return  \"rgba(\" + r + \", \" + g + \", \" + b + \", 1)\";\n        } else {\n            result = /^#?([a-f\\d]{2})([a-f\\d]{2})([a-f\\d]{2})$/i.exec(hex);\n            // 将分解出的分量转换为十进制数\n            let r = parseInt(result[1], 16);\n            let g = parseInt(result[2], 16);\n            let b = parseInt(result[3], 16);\n            return \"rgba(\" + r + \", \" + g + \", \" + b + \", 1)\";\n        }\n    }\n    // 将rgba值转为webGl色值\n    function rgbaToWebGL(rgba) {\n        // Split the RGBA string into its component parts\n        const parts = rgba.match(/\\d+/g);\n        // Extract the values for each component (red, green, blue, alpha)\n        const r = parseInt(parts[0], 10) / 255.0;\n        const g = parseInt(parts[1], 10) / 255.0;\n        const b = parseInt(parts[2], 10) / 255.0;\n        const a = parseInt(parts[3], 10);\n        // Return the WebGL color value\n        return {r,g,b,a};\n    }\n \n    // 将css两种色值（十六进制、rgba）表达式转为webgl色值\n    function cssToWebgl(cssColor){\n        const hexadecimalRegex1 =  /^#?([a-f\\d])([a-f\\d])([a-f\\d])$/i;\n        const hexadecimalRegex2 =  /^#?([a-f\\d]{2})([a-f\\d]{2})([a-f\\d]{2})$/i;\n        const rgbaRegex = /rgba\\((\\d+),\\s*(\\d+),\\s*(\\d+),\\s*(\\d\\.?\\d*)\\)/;\n        // 如果是十六进制那么转为rgb\n        if(hexadecimalRegex1.test(cssColor)||hexadecimalRegex2.test(cssColor)){\n            const hexadecimalToRgba = hexToRgba(cssColor) // 十六进制那么转为rgba\n            return rgbaToWebGL(hexadecimalToRgba) // 再将rgba值转为webGl色值\n        }else if(rgbaRegex.test(cssColor)){\n            return rgbaToWebGL(cssColor)\n        }else{\n            alert('请输入正确的十六进制、rgba表达式：（#f0f|#ff00ff|rgba(255,0,255,0.4)）')\n        }\n    }\n\n    /*\n        着色器是申明attribute变量\n        attribute变量赋值给gl_Position\n        向attribute变量传递变量\n     */\n    //顶点着色器程序\n    var VSHADER_SOURCE = \n    'attribute vec4 a_Position;\\n'+ \n    'void main(){\\n'+\n    ' gl_Position = a_Position;\\n'+\n    ' gl_PointSize = 10.0;\\n'+\n    '}\\n';\n\n    // //片元着色器\n    var FSHADER_SOURCE = \n    'precision mediump float;\\n'+ //精度限定词\n    'uniform vec4 u_FragColor;\\n'+\n    'void main(){\\n'+\n    ' gl_FragColor = u_FragColor;\\n'+\n    '}\\n';\n \n\n    var canvas = document.getElementById('webgl')\n    var gl = initWebGL(canvas)\n    if(!gl){\n        console.log('Failed to get thd rendering context for webgl')\n        return;\n    }\n\n    //初始着色器\n    if(!initShaders(gl,VSHADER_SOURCE,FSHADER_SOURCE)){\n        console.log('failed to initialize shaders')\n        return;\n    }\n\n    //获取变量attribute的存储位置\n    var a_Position = gl.getAttribLocation(gl.program,'a_Position');\n    if(a_Position < 0){\n        console.log('failed to get the storage location of a_Position')\n    }  \n    //获到u_FragColor变量的存储位置\n    var u_FragColor = gl.getUniformLocation(gl.program,'u_FragColor');\n    if(!u_FragColor){\n        console.log('failed to get u_FragColor variable');\n    }\n\n   canvas.onmousedown = function(ev){click(ev,gl,canvas,a_Position);}\n\n    //将顶点位置传输给attribute变量\n    //gl.vertexAttrib3f(a_Position,0.0,0.0,0.0); \n\n\n    var g_points = [];  //鼠标点击位置数组\n    var g_colors  =[];  //存储点颜色的数组\n    function click(ev,gl,canvas,a_Position){\n        // var x = ev.clientX;\n        // var y = ev.clientY;\n        // var rect = ev.target.getBoundingClientRect();\n        // x = ((x - rect.left) - canvas.width/2)/(canvas.width/2);\n        // y = ( canvas.height/2-(y-rect.top))/(canvas.height/2);\n\n        const [x, y] = getWebGLCoord(canvas, ev.clientX, ev.clientY);\n\n\n        console.log(x,y);\n        g_points.push([x,y]);\n\n        //将点的颜色存储到g_colors中\n        if(x>=0.0 && y>=0.0){ //第一象限\n\n            let {r,g,b,a} = cssToWebgl('#ff0000');\n            // g_colors.push([1.0,0.0,0.0,1.0]); //红色\n            g_colors.push([r,g,b,a]); //红色\n\n        }else if(x<0.0 && y<0.0){  //第三象限\n            console.log('第三象限')\n            let {r,g,b,a} = cssToWebgl('#00ff1e');\n            // g_colors.push([0.0,1.0,0.0,1.0]); //绿色\n            g_colors.push([r,g,b,a]); //绿色\n\n        }else{                      //其它\n             let {r,g,b,a} = cssToWebgl('#ffffff');\n            // g_colors.push([1.0,1.0,1.0,1.0]);//白色\n            g_colors.push([r,g,b,a]);//白色\n\n        }\n\n        // //清空<canvas>\n        gl.clear(gl.COLOR_BUFFER_BIT)\n        var len = g_points.length;\n        for(var i=0;i<len;i++){\n            var xy = g_points[i];\n            var rgba = g_colors[i];\n            //将点的位置传递到变量中\n            gl.vertexAttrib3f(a_Position,xy[0],xy[1],0.0)\n\n            //将点的颜色传输到u_FragColor变量中\n            gl.uniform4f(u_FragColor,rgba[0],rgba[1],rgba[2],rgba[3]);\n\n            //绘制点\n            gl.drawArrays(gl.POINTS,0,1)\n        }\n        \n    }\n\n    \n\n\n    //设置<canvas>背景色\n    // gl.clearColor(0.0,0.0,0.0,1.0);\n\n    // //清空<canvas>\n    // gl.clear(gl.COLOR_BUFFER_BIT)\n\n    // //绘制一个点\n    // gl.drawArrays(gl.POINTS,0,1)\n    \n\n}\n")])])])])}),[],!1,null,null,null);e.default=t.exports}}]);